-- ---------------------------------------------------------------------------
-- Q1. Listings with their city, country and owner (3-way JOIN)
-- Concepts: INNER JOIN, ORDER BY, LIMIT
-- ---------------------------------------------------------------------------
SELECT l.id, l.title, c.name AS city, co.isoCode AS country, u.name AS owner, l.price, l.currency
FROM Listing l
JOIN City c     ON c.id = l.cityId
JOIN Country co ON co.id = c.countryId
JOIN User u     ON u.id = l.ownerId
WHERE l.status = 'ACTIVE'
ORDER BY l.price DESC
LIMIT 5;
-- Result:
-- | id | title                                       | city      | country | owner                 | price | currency |
-- |----|---------------------------------------------|-----------|---------|-----------------------|-------|----------|
-- | 44 | 2-bedroom flat for sharing · Bengaluru      | Bengaluru | IN      | CityNest Global       | 48420 | INR      |
-- | 46 | Shared twin room in friendly WG · Bengaluru | Bengaluru | IN      | CityNest Global       | 20910 | INR      |
-- | 45 | Bright dorm bed near campus · Bengaluru     | Bengaluru | IN      | CityNest Global       | 14650 | INR      |
-- | 9  | Family-size apartment with garden · Zürich  | Zürich    | CH      | Alpine Student Living | 2670  | CHF      |
-- | 16 | 2-bedroom flat for sharing · Geneva         | Genève    | CH      | LakeView Residences   | 2630  | CHF      |

-- ---------------------------------------------------------------------------
-- Q2. Search cards straight from the view v_listing_summary
-- Concepts: VIEW (joins + scalar sub-queries + stored function fn_spots_left)
-- ---------------------------------------------------------------------------
SELECT id, cityName, type, price, currency, spotsLeft, photoCount, openRequests, ownerVerified
FROM v_listing_summary
WHERE status = 'ACTIVE' AND isShareable = TRUE AND spotsLeft > 0
ORDER BY openRequests DESC, price
LIMIT 5;
