-- ---------------------------------------------------------------------------
-- Q3. Cities with at least 3 active listings and their price statistics
-- Concepts: GROUP BY, HAVING, aggregate functions (COUNT, AVG, MIN, MAX)
-- ---------------------------------------------------------------------------
SELECT c.name AS city, COUNT(*) AS listings, ROUND(AVG(l.price)) AS avg_price, MIN(l.price) AS min_price, MAX(l.price) AS max_price
FROM Listing l JOIN City c ON c.id = l.cityId
WHERE l.status = 'ACTIVE'
GROUP BY c.id, c.name
HAVING COUNT(*) >= 3
ORDER BY listings DESC;
-- Result:
-- | city      | listings | avg_price | min_price | max_price |
-- |-----------|----------|-----------|-----------|-----------|
-- | Zürich    | 12       | 1221      | 730       | 2670      |
-- | Genève    | 6        | 1265      | 740       | 2630      |
-- | Lausanne  | 5        | 1152      | 620       | 2030      |
-- | Basel     | 4        | 923       | 640       | 1450      |
-- | Bern      | 4        | 1028      | 680       | 1940      |
-- | Bengaluru | 3        | 27993     | 14650     | 48420     |
-- | Berlin    | 3        | 720       | 540       | 960       |

-- ---------------------------------------------------------------------------
-- Q4. Listings cheaper than the average of their own city
-- Concepts: Correlated sub-query
-- ---------------------------------------------------------------------------
SELECT l.id, l.title, l.price,
       (SELECT ROUND(AVG(l2.price)) FROM Listing l2 WHERE l2.cityId = l.cityId AND l2.status = 'ACTIVE') AS city_avg
FROM Listing l
WHERE l.status = 'ACTIVE'
  AND l.price < (SELECT AVG(l2.price) FROM Listing l2 WHERE l2.cityId = l.cityId AND l2.status = 'ACTIVE')
ORDER BY l.price
LIMIT 5;
-- Result:
-- | id | title                                        | price | city_avg |
-- |----|----------------------------------------------|-------|----------|
-- | 41 | Shared twin room in friendly WG · Berlin     | 540   | 720      |
-- | 21 | Bright dorm bed near campus · Lausanne       | 620   | 1152     |
-- | 32 | Shared twin room in friendly WG · Lucerne    | 630   | 770      |
-- | 24 | Bright dorm bed near campus · Basel          | 640   | 923      |
-- | 42 | Sunny private room in a 4-person WG · Berlin | 660   | 720      |

-- ---------------------------------------------------------------------------
-- Q5. Rank listings by price inside each city
-- Concepts: Window functions RANK() and PERCENT_RANK() with PARTITION BY
-- ---------------------------------------------------------------------------
SELECT c.name AS city, l.title, l.price,
       RANK() OVER (PARTITION BY l.cityId ORDER BY l.price) AS price_rank,
       ROUND(PERCENT_RANK() OVER (PARTITION BY l.cityId ORDER BY l.price) * 100) AS percentile
FROM Listing l JOIN City c ON c.id = l.cityId
WHERE l.status = 'ACTIVE' AND c.name IN ('Zürich', 'Genève')
ORDER BY city, price_rank
LIMIT 8;
-- Result:
-- | city   | title                                        | price | price_rank | percentile |
-- |--------|----------------------------------------------|-------|------------|------------|
-- | Genève | Spacious shared room with balcony · Geneva   | 740   | 1          | 0          |
-- | Genève | Bright dorm bed near campus · Geneva         | 790   | 2          | 20         |
-- | Genève | Shared twin room in friendly WG · Geneva     | 950   | 3          | 40         |
-- | Genève | Sunny private room in a 4-person WG · Geneva | 1130  | 4          | 60         |
-- | Genève | Furnished studio with kitchenette · Geneva   | 1350  | 5          | 80         |
-- | Genève | 2-bedroom flat for sharing · Geneva          | 2630  | 6          | 100        |
-- | Zürich | Spacious shared room with balcony · Zürich   | 730   | 1          | 0          |
-- | Zürich | Bright dorm bed near campus · Zürich         | 750   | 2          | 9          |

-- ---------------------------------------------------------------------------
-- Q6. Nearest listings to Zürich main station
-- Concepts: Stored FUNCTION fn_distance_km (Haversine) used in SELECT and ORDER BY
-- ---------------------------------------------------------------------------
SELECT id, title, ROUND(fn_distance_km(47.3779, 8.5403, lat, lng), 2) AS km
FROM Listing
WHERE lat IS NOT NULL
ORDER BY km
LIMIT 5;
-- Result:
-- | id | title                                            | km   |
