-- ---------------------------------------------------------------------------
-- Q7. Full-text search over listing titles and descriptions
-- Concepts: FULLTEXT index + MATCH … AGAINST in BOOLEAN MODE, relevance score
-- ---------------------------------------------------------------------------
SELECT id, title, ROUND(MATCH(title, description) AGAINST ('+balcony* +shared*' IN BOOLEAN MODE), 3) AS relevance
FROM Listing
WHERE MATCH(title, description) AGAINST ('+balcony* +shared*' IN BOOLEAN MODE)
ORDER BY relevance DESC
LIMIT 5;
-- Result:
-- | id | title                                      | relevance |
-- |----|--------------------------------------------|-----------|
-- | 18 | Spacious shared room with balcony · Geneva | 1.995     |
-- | 6  | Spacious shared room with balcony · Zürich | 1.924     |

-- ---------------------------------------------------------------------------
-- Q8. Full-text search over the settling-in guide
-- Concepts: FULLTEXT on three columns (title, summary, body)
-- ---------------------------------------------------------------------------
SELECT slug, title, ROUND(MATCH(title, summary, body) AGAINST ('insurance deductible' IN NATURAL LANGUAGE MODE), 3) AS score
FROM GuideArticle
WHERE MATCH(title, summary, body) AGAINST ('insurance deductible' IN NATURAL LANGUAGE MODE)
ORDER BY score DESC;
