-- ---------------------------------------------------------------------------
-- Q16. Planned trip spend per category
-- Concepts: GROUP BY on an enum, JOIN to the parent row
-- ---------------------------------------------------------------------------
SELECT i.title AS trip, it.kind, COUNT(*) AS items, SUM(it.estimatedCost) AS spent, i.budget, i.currency
FROM Itinerary i JOIN ItineraryItem it ON it.itineraryId = i.id
GROUP BY i.id, i.title, it.kind, i.budget, i.currency
ORDER BY i.id, spent DESC
LIMIT 8;
