-- ---------------------------------------------------------------------------
-- Q17. Closest pharmacy to each seeded Swiss city centre
-- Concepts: ROW_NUMBER() window over a computed distance
-- ---------------------------------------------------------------------------
SELECT city, pharmacy, km FROM (
  SELECT c.name AS city, p.name AS pharmacy, ROUND(fn_distance_km(c.lat, c.lng, p.lat, p.lng), 2) AS km,
         ROW_NUMBER() OVER (PARTITION BY c.id ORDER BY fn_distance_km(c.lat, c.lng, p.lat, p.lng)) AS rn
  FROM City c JOIN POI p ON p.category = 'PHARMACY' AND p.lat BETWEEN c.lat - 0.05 AND c.lat + 0.05 AND p.lng BETWEEN c.lng - 0.07 AND c.lng + 0.07
  WHERE c.name IN ('Zürich', 'Genève', 'Lausanne', 'Bern')
) ranked
WHERE rn = 1;
-- Result:
-- | city     | pharmacy            | km   |
-- |----------|---------------------|------|
-- | Genève   | Pharmacie Populaire | 0.24 |
-- | Lausanne | Pharmacie Populaire | 0.13 |
-- | Zürich   | Amavita             | 0.08 |

-- ---------------------------------------------------------------------------
-- Q18. Trigger: a price change is written to AuditLog automatically
-- Concepts: UPDATE + AFTER UPDATE trigger trg_listing_audit_au (rolled back)
-- ---------------------------------------------------------------------------
START TRANSACTION;
UPDATE Listing SET price = price + 50 WHERE id = 1;
SELECT tableName, rowId, action, oldValue, newValue FROM AuditLog ORDER BY id DESC LIMIT 1;
ROLLBACK;
-- Result:
-- | tableName | rowId | action | oldValue                        | newValue                        |
-- |-----------|-------|--------|---------------------------------|---------------------------------|
-- | Listing   | 1     | UPDATE | {"price":830,"status":"ACTIVE"} | {"price":880,"status":"ACTIVE"} |

