-- Q20. CHECK constraint: occupants can never exceed capacity
-- Concepts: Domain integrity enforced by the database (chk_listing_occupants)
-- ---------------------------------------------------------------------------
START TRANSACTION;
UPDATE Listing SET currentOccupants = capacityMax + 1 WHERE id = 1;
ROLLBACK;
